#include "exgine/lexer.hpp"
#include <cctype>
#include <string>
#include <unordered_map>
#include <utility>
namespace exgine{namespace{TokenKind kw(std::string_view w){static const std::unordered_map<std::string_view,TokenKind>m{{"game",TokenKind::Game},{"world",TokenKind::World},{"terrain",TokenKind::Terrain},{"vegetation",TokenKind::Vegetation},{"building",TokenKind::Building},{"vehicle",TokenKind::Vehicle},{"player",TokenKind::Player},{"npc",TokenKind::NPC},{"bridge",TokenKind::Bridge},{"prop",TokenKind::Prop},{"procedural",TokenKind::Procedural},{"true",TokenKind::True},{"false",TokenKind::False}};auto i=m.find(w);return i==m.end()?TokenKind::Identifier:i->second;}}
std::vector<Token>Lexer::tokenize(DiagnosticBag&d)const{std::vector<Token>o;std::size_t i=0,l=1,c=1;auto adv=[&](std::size_t n=1){while(n--&&i<source_.size()){if(source_.at(i)=='\n'){++l;c=1;}else++c;++i;}};auto loc=[&]{return SourceLocation{i,l,c};};while(i<source_.size()){char ch=source_.at(i);if(std::isspace((unsigned char)ch)){adv();continue;}if(ch=='/'&&i+1<source_.size()&&source_.at(i+1)=='/'){while(i<source_.size()&&source_.at(i)!='\n')adv();continue;}auto s=loc();if(std::isalpha((unsigned char)ch)||ch=='_'){auto b=i;while(i<source_.size()&&(std::isalnum((unsigned char)source_.at(i))||source_.at(i)=='_'))adv();std::string w(source_.text().substr(b,i-b));o.push_back({kw(w),w,s});continue;}if(std::isdigit((unsigned char)ch)||(ch=='-'&&i+1<source_.size()&&std::isdigit((unsigned char)source_.at(i+1)))){auto b=i;bool dec=false;if(ch=='-')adv();while(i<source_.size()&&std::isdigit((unsigned char)source_.at(i)))adv();if(i<source_.size()&&source_.at(i)=='.'){dec=true;adv();while(i<source_.size()&&std::isdigit((unsigned char)source_.at(i)))adv();}if(i<source_.size()&&source_.at(i)=='.'){d.error("invalid number: multiple decimal points",s);while(i<source_.size()&&(std::isdigit((unsigned char)source_.at(i))||source_.at(i)=='.'))adv();}o.push_back({dec?TokenKind::Number:TokenKind::Integer,std::string(source_.text().substr(b,i-b)),s});continue;}if(ch=='"'){adv();std::string v;bool closed=false;while(i<source_.size()){char q=source_.at(i);if(q=='"'){adv();closed=true;break;}if(q=='\n'){d.error("unterminated string literal",s);break;}if(q=='\\'){adv();if(i>=source_.size())break;char e=source_.at(i);switch(e){case'n':v+='\n';break;case'r':v+='\r';break;case't':v+='\t';break;case'"':v+='"';break;case'\\':v+='\\';break;default:d.error("unknown string escape",{i,l,c});v+=e;}adv();}else{v+=q;adv();}}if(closed)o.push_back({TokenKind::String,std::move(v),s});continue;}TokenKind k=TokenKind::EndOfFile;switch(ch){case'=':k=TokenKind::Equals;break;case'{':k=TokenKind::LeftBrace;break;case'}':k=TokenKind::RightBrace;break;case'[':k=TokenKind::LeftBracket;break;case']':k=TokenKind::RightBracket;break;case',':k=TokenKind::Comma;break;default:d.error("unexpected character '"+std::string(1,ch)+"'",s);adv();continue;}o.push_back({k,std::string(1,ch),s});adv();}o.push_back({TokenKind::EndOfFile,{}, {i,l,c}});return o;}}
